def transform(grid):
    sep = next(i for i, row in enumerate(grid) if all(x == 5 for x in row))
    colors = {x for row in grid for x in row if x not in (0, 5)}
    above, below = grid[:sep], grid[sep + 1:]
    ratios = {}
    for color in colors:
        a = sum(row.count(color) for row in above)
        b = sum(row.count(color) for row in below)
        ratios[color] = b / a if a else float('inf')
    color = max(colors, key=lambda c: (ratios[c], c))
    return [[color, color], [color, color]]
